export const SEAL_PATHS = [rosette(60, 60, 57, 24, 0.07), rosette(60, 60, 50, 16, 0.12), rosette(60, 60, 41, 12, 0.18), rosette(60, 60, 31, 8, 0.24), rosette(60, 60, 20, 5, 0.3)];
